input.command:
cat > package.json <<'EOF'
{
  "name": "acme-design-tokens",
  "version": "0.1.0",
  "private": true,
  "scripts": {
    "validate": "node -e \"['tokens.json','tokens-system.json'].forEach(f=>JSON.parse(require('fs').readFileSync(f,'utf8')))\""
  },
  "devDependencies": {
    "klar-cli": "3.0.0"
  }
}
EOF
npm run validate; echo "exit=$?"
echo '{bad' > /tmp/x.json 2>/dev/null; cp tokens.json $TMPDIR/tokens.bak 2>/dev/null || cp tokens.json ../tokens.bak
echo '{bad' > tokens.json; npm run validate 2>&1 | tail -5; echo "exit=${PIPESTATUS[0]}"
cp ../tokens.bak tokens.json 2>/dev/null || cp $TMPDIR/tokens.bak tokens.json; rm -f ../tokens.bak; git status --short

